-- Opt-in synthetic-erasure-v1 only. Never install on a production database.
CREATE TABLE r1_financial_jobs (
 id TEXT PRIMARY KEY REFERENCES r1_deletion_jobs(id), account_id INTEGER NOT NULL UNIQUE,
 policy_version TEXT NOT NULL, policy_digest TEXT NOT NULL, policy_json TEXT NOT NULL,
 confirmed_at INTEGER NOT NULL, financial_until INTEGER NOT NULL,
 stage TEXT NOT NULL DEFAULT 'minimize' CHECK(stage IN ('minimize','retained','purge','purged')),
 cursor INTEGER NOT NULL DEFAULT 0 CHECK(cursor>=0 AND cursor<=14),
 owner TEXT, lease_until INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0,
 minimized_at INTEGER, purged_at INTEGER
);
CREATE TABLE r1_financial_case_reviews (
 job_id TEXT PRIMARY KEY REFERENCES r1_financial_jobs(id), account_id INTEGER NOT NULL,
 confirmed_at INTEGER NOT NULL, policy_digest TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'unresolved' CHECK(status IN ('unresolved','resolved')),
 balance_disposition TEXT NOT NULL DEFAULT 'pending' CHECK(balance_disposition IN ('pending','zero-balance-confirmed')),
 checked_at INTEGER, evidence_digest TEXT, reviewer_ref TEXT
);
-- Exists only inside the atomic mutation batch. No long-lived capability is issued.
CREATE TABLE r1_financial_write_permits (
 job_id TEXT PRIMARY KEY REFERENCES r1_financial_jobs(id), account_id INTEGER NOT NULL,
 table_name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('minimize','purge')),
 row_ids_json TEXT NOT NULL CHECK(json_valid(row_ids_json) AND json_type(row_ids_json)='array' AND json_array_length(row_ids_json)<=200),
 owner TEXT NOT NULL, version INTEGER NOT NULL, checked_at INTEGER NOT NULL
);

