CREATE TRIGGER r1_financial_reader_credit_accounts_insert BEFORE INSERT ON reader_credit_accounts WHEN ((NEW.account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM reader_accounts WHERE id=NEW.account_id AND status='active')) OR NOT (EXISTS(SELECT 1 FROM reader_accounts WHERE id=NEW.account_id AND status='active'))) BEGIN SELECT RAISE(ABORT,'R1_FINANCIAL_INACTIVE_WRITE'); END;
CREATE TRIGGER r1_financial_reader_credit_accounts_update BEFORE UPDATE ON reader_credit_accounts WHEN (((OLD.account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM reader_accounts WHERE id=OLD.account_id AND status='active')) OR NOT (EXISTS(SELECT 1 FROM reader_accounts WHERE id=OLD.account_id AND status='active'))) OR ((NEW.account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM reader_accounts WHERE id=NEW.account_id AND status='active')) OR NOT (EXISTS(SELECT 1 FROM reader_accounts WHERE id=NEW.account_id AND status='active')))) AND NOT 0 BEGIN SELECT RAISE(ABORT,'R1_FINANCIAL_INACTIVE_WRITE'); END;
CREATE TRIGGER r1_financial_reader_credit_accounts_delete BEFORE DELETE ON reader_credit_accounts WHEN ((OLD.account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM reader_accounts WHERE id=OLD.account_id AND status='active')) OR NOT (EXISTS(SELECT 1 FROM reader_accounts WHERE id=OLD.account_id AND status='active'))) AND NOT (EXISTS(SELECT 1 FROM r1_financial_write_permits p JOIN r1_financial_jobs j ON j.id=p.job_id WHERE p.table_name='reader_credit_accounts' AND p.mode='purge' AND p.account_id=j.account_id AND p.owner=j.owner AND p.version=j.version AND j.stage='purge' AND j.lease_until>p.checked_at AND ((OLD.account_id IS NULL OR OLD.account_id=p.account_id) AND (OLD.account_id=p.account_id)) AND EXISTS(SELECT 1 FROM json_each(p.row_ids_json) WHERE value=OLD.rowid))) BEGIN SELECT RAISE(ABORT,'R1_FINANCIAL_DELETE_PERMIT_REQUIRED'); END;
