ader_credit_ledger WHERE id=NEW.ledger_id)))) AND NOT (EXISTS(SELECT 1 FROM r1_financial_write_permits p JOIN r1_financial_jobs j ON j.id=p.job_id WHERE p.table_name='reader_membership_redemptions' AND p.mode='minimize' AND p.account_id=j.account_id AND p.owner=j.owner AND p.version=j.version AND j.stage='minimize' AND j.lease_until>p.checked_at AND ((OLD.account_id IS NULL OR OLD.account_id=p.account_id) AND (OLD.ledger_id IS NULL OR EXISTS(SELECT 1 FROM reader_credit_ledger WHERE id=OLD.ledger_id AND account_id=p.account_id)) AND (OLD.account_id=p.account_id OR (SELECT account_id FROM reader_credit_ledger WHERE id=OLD.ledger_id)=p.account_id)) AND EXISTS(SELECT 1 FROM json_each(p.row_ids_json) WHERE value=OLD.rowid)) AND NEW.rowid=OLD.rowid AND NEW.account_id IS OLD.account_id AND NEW.request_key IS OLD.request_key AND NEW.operation_token IS OLD.operation_token AND NEW.cost_credits IS OLD.cost_credits AND NEW.duration_months IS OLD.duration_months AND NEW.unit_label IS OLD.unit_label AND NEW.covers_paid IS OLD.covers_paid AND NEW.balance_before IS OLD.balance_before AND NEW.previous_expires_at IS OLD.previous_expires_at AND NEW.ledger_id IS OLD.ledger_id AND NEW.applied IS OLD.applied AND NEW.created_at IS OLD.created_at AND (NEW.membership_json IS NULL OR NEW.membership_json='{}')) BEGIN SELECT RAISE(ABORT,'R1_FINANCIAL_INACTIVE_WRITE'); END;
